/* From Uiverse.io by lenin55 - Tags: material design, checkbox */
.__UIV_SCOPE__ .cl-checkbox {
 position: relative;
 display: inline-block;
}

/* Input */
.__UIV_SCOPE__ .cl-checkbox > input {
 appearance: none;
 -moz-appearance: none;
 -webkit-appearance: none;
 z-index: -1;
 position: absolute;
 left: -10px;
 top: -8px;
 display: block;
 margin: 0;
 border-radius: 50%;
 width: 40px;
 height: 40px;
 background-color: rgba(0, 0, 0, 0.6);
 box-shadow: none;
 outline: none;
 opacity: 0;
 transform: scale(1);
 pointer-events: none;
 transition: opacity 0.3s, transform 0.2s;
}

/* Span */
.__UIV_SCOPE__ .cl-checkbox > span {
 display: inline-block;
 width: 100%;
 cursor: pointer;
}

/* Box */
.__UIV_SCOPE__ .cl-checkbox > span::before {
 content: "";
 display: inline-block;
 box-sizing: border-box;
 margin: 3px 11px 3px 1px;
 border: solid 2px;
 /* Safari */
 border-color: rgba(0, 0, 0, 0.6);
 border-radius: 2px;
 width: 18px;
 height: 18px;
 vertical-align: top;
 transition: border-color 0.2s, background-color 0.2s;
}

/* Checkmark */
.__UIV_SCOPE__ .cl-checkbox > span::after {
 content: "";
 display: block;
 position: absolute;
 top: 3px;
 left: 1px;
 width: 10px;
 height: 5px;
 border: solid 2px transparent;
 border-right: none;
 border-top: none;
 transform: translate(3px, 4px) rotate(-45deg);
}

/* Checked, Indeterminate */
.__UIV_SCOPE__ .cl-checkbox > input:checked,
.__UIV_SCOPE__ .cl-checkbox > input:indeterminate {
 background-color: #018786;
}

.__UIV_SCOPE__ .cl-checkbox > input:checked + span::before,
.__UIV_SCOPE__ .cl-checkbox > input:indeterminate + span::before {
 border-color: #018786;
 background-color: #018786;
}

.__UIV_SCOPE__ .cl-checkbox > input:checked + span::after,
.__UIV_SCOPE__ .cl-checkbox > input:indeterminate + span::after {
 border-color: #fff;
}

.__UIV_SCOPE__ .cl-checkbox > input:indeterminate + span::after {
 border-left: none;
 transform: translate(4px, 3px);
}

/* Hover, Focus */
.__UIV_SCOPE__ .cl-checkbox:hover > input {
 opacity: 0.04;
}

.__UIV_SCOPE__ .cl-checkbox > input:focus {
 opacity: 0.12;
}

.__UIV_SCOPE__ .cl-checkbox:hover > input:focus {
 opacity: 0.16;
}

/* Active */
.__UIV_SCOPE__ .cl-checkbox > input:active {
 opacity: 1;
 transform: scale(0);
 transition: transform 0s, opacity 0s;
}

.__UIV_SCOPE__ .cl-checkbox > input:active + span::before {
 border-color: #85b8b7;
}

.__UIV_SCOPE__ .cl-checkbox > input:checked:active + span::before {
 border-color: transparent;
 background-color: rgba(0, 0, 0, 0.6);
}

/* Disabled */
.__UIV_SCOPE__ .cl-checkbox > input:disabled {
 opacity: 0;
}

.__UIV_SCOPE__ .cl-checkbox > input:disabled + span {
 color: rgba(0, 0, 0, 0.38);
 cursor: initial;
}

.__UIV_SCOPE__ .cl-checkbox > input:disabled + span::before {
 border-color: currentColor;
}

.__UIV_SCOPE__ .cl-checkbox > input:checked:disabled + span::before,
.__UIV_SCOPE__ .cl-checkbox > input:indeterminate:disabled + span::before {
 border-color: transparent;
 background-color: currentColor;
}
